CREATE TABLE IF NOT EXISTS usuarios (id BIGSERIAL PRIMARY KEY,nome VARCHAR(150) NOT NULL,documento VARCHAR(14) UNIQUE NOT NULL,data_nascimento DATE NOT NULL,email VARCHAR(254) UNIQUE NOT NULL,senha_hash VARCHAR(255) NOT NULL,perfil VARCHAR(20) NOT NULL DEFAULT 'CLIENTE',criado_em TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,atualizado_em TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP)@@ CREATE OR REPLACE FUNCTION usuarios_trigger() RETURNS trigger AS $$ BEGIN NEW.atualizado_em=CURRENT_TIMESTAMP; NEW.email=lower(trim(NEW.email)); NEW.documento=regexp_replace(NEW.documento,'[^0-9]','','g'); RETURN NEW; END; $$ LANGUAGE plpgsql@@ DROP TRIGGER IF EXISTS usuarios_atualizacao ON usuarios@@ CREATE TRIGGER usuarios_atualizacao BEFORE INSERT OR UPDATE ON usuarios FOR EACH ROW EXECUTE FUNCTION usuarios_trigger()@@
